import React from 'react';

const App = () => {
  // Redirect to backend to handle Spotify authentication
  const handleLogin = () => {
    window.location.href = 'http://localhost:3001/api/login';
  };

  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1>Spotify Simple Login</h1>
      <p>Click the button below to login with Spotify.</p>
      <button
        onClick={handleLogin}
        style={{
          padding: '10px 20px',
          fontSize: '16px',
          backgroundColor: '#1DB954',
          color: 'white',
          border: 'none',
          cursor: 'pointer',
        }}
      >
        Login with Spotify
      </button>
    </div>
  );
};

export default App;
